     function App() {
       return createElement("div", { className: "page-shell" }, [
         Header(),
         createElement("main", {
           attrs: {
             id: "main-content"
           }
         }, [
           Hero(),
           createElement("div", { className: "content-grid" }, [
             PreviewCard(),
             DetailsPanel()
           ])
         ]),
         ConfirmDialog()
       ]);
     }

     document.getElementById("app-root").appendChild(App());

     const dialog = document.getElementById("confirm-dialog");
     const openDialogButton = document.getElementById("open-dialog-button");
     const cancelDialogButton = document.getElementById("cancel-dialog-button");
     const confirmDeleteButton = document.getElementById("confirm-delete-button");
     const statusText = document.getElementById("image-status");
     let lastFocusedElement = null;

     function openDialog() {
       lastFocusedElement = document.activeElement;
       dialog.showModal();
       cancelDialogButton.focus();
     }

     function closeDialog() {
       dialog.close();
     }

     function handleDelete() {
       statusText.textContent = "This image has been deleted from your library.";
       statusText.dataset.state = "deleted";
       openDialogButton.disabled = true;
       closeDialog();
     }

     openDialogButton.addEventListener("click", openDialog);
     cancelDialogButton.addEventListener("click", closeDialog);
     confirmDeleteButton.addEventListener("click", handleDelete);

     dialog.addEventListener("click", (event) => {
       const bounds = dialog.getBoundingClientRect();
       const clickedInDialog =
         event.clientX >= bounds.left &&
         event.clientX <= bounds.right &&
         event.clientY >= bounds.top &&
         event.clientY <= bounds.bottom;

       if (!clickedInDialog) {
         closeDialog();
       }
     });

     dialog.addEventListener("close", () => {
       if (
         lastFocusedElement instanceof HTMLElement &&
         !lastFocusedElement.hasAttribute("disabled")
       ) {
         lastFocusedElement.focus();
       } else {
         statusText.focus();
       }
     });
   </script>
